"""Original, version-neutral applied security foundations for Athena.

No network, filesystem, account or security-setting operations on import.
The first check uses Athena's existing lesson schema. Additional checks and
teaching metadata are explicit fields for future UI support and documentation.
"""
LESSONS = []
S = {
 'risk': 'https://nvlpubs.nist.gov/nistpubs/Legacy/SP/nistspecialpublication800-30r1.pdf',
 'csf': 'https://www.nist.gov/cyberframework',
 'identity': 'https://pages.nist.gov/800-63-4/sp800-63b.html',
 'zero': 'https://csrc.nist.gov/pubs/sp/800/207/final',
 'hash': 'https://csrc.nist.gov/pubs/fips/180-4/upd1/final',
 'python_hash': 'https://docs.python.org/3/library/hashlib.html',
 'python_hmac': 'https://docs.python.org/3/library/hmac.html',
 'patch': 'https://csrc.nist.gov/pubs/sp/800/40/r4/final',
 'cvss': 'https://www.first.org/cvss/v4.0/user-guide',
 'logging': 'https://cheatsheetseries.owasp.org/cheatsheets/Logging_Cheat_Sheet.html',
 'incident': 'https://csrc.nist.gov/pubs/sp/800/61/r3/final',
 'recovery': 'https://csrc.nist.gov/pubs/sp/800/34/r1/upd1/final',
 'dmarc': 'https://www.rfc-editor.org/rfc/rfc7489.html',
 'phishing': 'https://www.ftc.gov/business-guidance/small-businesses/cybersecurity',
}

def check(question, options, answer, why):
 return dict(question=question, options=options, answer=answer, why=why)

def add(id, title, summary, goals, paragraphs, example, practice, checks, sources, proof, limits):
 assert len(checks) == 3
 # Rotate the correct choice across the 30 original checks, without moving meaning.
 for n,c in enumerate(checks):
  correct = c['options'].pop(c['answer'])
  c['answer'] = (len(LESSONS)*3+n) % 4
  c['options'].insert(c['answer'],correct)
 LESSONS.append(dict(id=id,title=title,category='Security',summary=summary,
  explain=paragraphs,example=example,lab=practice,**checks[0],
  tags=['security-foundations','security-plus','general-security'],
  sources=[S[s] for s in sources],depth='applied foundation + synthetic/offline practice',
  estimatedMinutes=40, learningGoals=goals, additionalChecks=checks[1:],
  evidence=proof, limitations=limits))

add('sec-risk-story','Describe the risk before choosing a tool',
 'Turn a vague security worry into a concrete scenario, a control and a test.',
 ['Separate assets, threats, vulnerabilities and consequences.','Explain confidentiality, integrity and availability in a business workflow.','Record residual risk without pretending a simple score is a forecast.'],[
 'Begin with something people need to accomplish. A fictional repair cooperative, Cedar Workshop, keeps booking records and equipment instructions. The valuable assets include the records, the booking service, the staff identities and the ability to open on time. A security decision should preserve a useful outcome, not merely accumulate products.',
 'Confidentiality means restricting disclosure to the intended people. Integrity means preventing or detecting inappropriate changes. Availability means that authorized people can use the service when needed. Publishing a customer list harms confidentiality; changing appointment times harms integrity; losing the service during opening hours harms availability. One event can affect all three.',
 'A threat is a possible cause of harm. A vulnerability is a weakness that could contribute to it. Risk describes the possibility and consequences of a scenario in context. Write a sentence: a former contractor could use an account left active to change bookings, interrupting service. The person, stale account, unwanted change and business impact have different roles in that sentence.',
 'A control changes that scenario. An access review can find stale accounts; disabling an account can prevent future use; an audit trail can help detect changes; a tested restore can recover records. Preventive, detective and corrective describe a control’s purpose. Technical, administrative and physical describe how it is implemented. These are different axes, and a control can serve more than one purpose.',
 'Use a simple likelihood/impact scale only with written meanings. Multiplying two labels from 1 to 3 can organize discussion, but does not estimate a precise probability or expected loss. Two risks with equal products may require different decisions. Record exposure, assumptions, uncertainty and the owner who can accept the remaining risk.',
 'Avoidance stops the risky activity, mitigation reduces the risk, transfer or sharing changes who bears some consequences, and acceptance deliberately keeps a risk within an authorized tolerance. Buying insurance does not prevent an outage or erase operational duties. After controls, residual risk remains. Revisit it when the service, threat, evidence or business need changes.'
 ],
 'Cedar has 12 staff and one departed contractor. Fictional scenario R1 is unauthorized booking changes through the contractor’s active account. The service owner chooses account removal, a monthly access review and change logging. Verification is not “we bought identity software”: inspect the approved account inventory, test a simulated deny for the departed identity, and check that a synthetic change produces an audit event. Residual risk includes misuse by a current authorized staff member. Name the service owner and a review date instead of claiming zero risk.',
 ['Use the supplied evidence worksheet; do not inventory real customers.','Write three Cedar scenarios, each naming asset, threat, weakness and consequence.','For each scenario identify confidentiality, integrity and/or availability impact.','Choose one preventive and one detective or corrective control, with a named fictional owner.','State a concrete verification observation and a residual risk.','Explain one case where the highest numeric score should not automatically dictate the next action.'],[
 check('A contractor leaves but their account still permits booking changes. Which item is the vulnerability?', ['The booking service’s business value','The account remains usable without a valid business need','All contractors are attackers','The cost of cancelling appointments'],1,'The stale access is the weakness. Intent, asset value and consequences are separate parts of the risk story.'),
 check('A change log helps discover unauthorized edits. What is its primary purpose in this scenario?', ['Detective','It guarantees confidentiality','It eliminates all residual risk','It transfers legal responsibility'],0,'The log supports detection and investigation. It does not automatically prevent editing or remove responsibility.'),
 check('What makes a residual-risk entry useful?', ['A guarantee that nothing bad can happen','A product name alone','A stated remaining scenario, owner and review trigger','A bigger unexplained score'],2,'Residual risk must be understood and owned; a score or product label is not a decision record.')
 ],['risk','csf'],
 ['Three scenario records with distinct threats and weaknesses.','Control purpose and verification are connected to each scenario.','Uncertainty, residual risk and owner are stated.'],
 'A small qualitative exercise is not an enterprise risk assessment or a financial loss forecast.')

add('sec-identity-lifecycle','Design access that ends when the job ends',
 'Connect authentication, least privilege, access review and safe recovery.',
 ['Distinguish authentication, authorization and auditing.','Evaluate factor categories and recovery weaknesses.','Test lifecycle and object-level access with synthetic identities.'],[
 'Authentication checks a claim about identity; authorization decides whether that identity may perform this action on this resource; auditing records relevant activity. Cedar’s receptionist can be correctly signed in yet forbidden to export all records. That denial is normal least privilege, not necessarily a broken login.',
 'A role is a convenient bundle of job permissions, not a reason to grant everything. Attribute-based decisions can also consider the resource owner, device state or an approved temporary assignment. A server must enforce decisions on every relevant request. Hiding an export button in the interface does not stop a direct request.',
 'Two pieces of the same kind of evidence are not automatically two factors. Two passwords are both knowledge. A device-held cryptographic credential activated with a local PIN or biometric can combine possession with another factor. A biometric alone is not a secret that can be replaced after disclosure. Different mechanisms and deployments have different assurance properties.',
 'Phishing-resistant authentication binds the proof to the intended service rather than simply asking someone to copy a reusable secret or code. Prefer supported phishing-resistant methods, but examine enrollment, device replacement, session management and recovery too. A strong normal login can be undermined by a weak recovery path. Do not infer that every method called MFA has equal resistance.',
 'Access has a lifecycle: approve and provision for a real need, change access when the role changes, review it, and remove it when the need ends. Machine identities need owners and scoped permissions as well. Time-limited administrative access reduces standing exposure, but only if expiration and revocation are actually enforced.',
 'For this exercise, policy inputs are invented. Our evaluator requires an active identity, an approved managed device and a role/action match. It denies everything else. These rules teach explicit policy and negative testing; they are not a model of every cloud IAM system. No real account, device policy, password or authenticator is changed.'
 ],
 'Synthetic policy: receptionist may read and update bookings; auditor may read bookings; backup-service may read a backup snapshot; administrator may manage accounts but does not inherit booking-export rights. Dana is a departed receptionist, so active=false must deny even an otherwise permitted read. Ari is an active auditor on an unmanaged device, so the toy policy denies that read too. The important test is not only “a permitted request works”; forbidden action, wrong resource, inactive identity and missing conditions must fail.',
 ['Read access-cases.json and predict each allow/deny outcome before using the tool.','Run python3 labs/security-foundations/offline_lab.py access from the pack root.','Match each decision to a written policy rule and inspect denied cases.','Explain why account administration and data export need not be the same role.','Write a fictional joiner, role-change and leaver checklist with a revocation check.','Record a recovery threat and how an approved help process would verify identity without asking for a password.'],[
 check('A valid user cannot access another customer’s record. Which security function is deciding?', ['Authorization','DNS','Disk encryption alone','Authentication must always have failed'],0,'The decision concerns an action on an object after an identity is known.'),
 check('Which pair is not two different factor categories?', ['A device-held key and a local activation PIN','Two different memorized passwords','Possession and knowledge','Possession and a biometric activation factor'],1,'Changing the number of passwords does not change the factor category.'),
 check('Why test an inactive identity with an otherwise valid role?', ['Because role membership should bypass termination','Because successful login proves every permission','Because it checks that lifecycle revocation overrides an old entitlement','Because auditors need administrator access'],2,'A leaver can retain an old role record. An active-status gate must still prevent access in this toy policy.')
 ],['identity','zero'],
 ['Predictions and actual outcomes for all eight access cases.','At least four different deny reasons explained.','Lifecycle checklist includes a verification step.'],
 'This toy authorization engine does not implement federation, OAuth, SAML, vendor IAM evaluation, account recovery or real authentication.')

add('sec-data-integrity','Tell secrecy, integrity and authenticity apart',
 'Use a local hash experiment to learn what cryptography does and does not prove.',
 ['Select hashing, encryption, MACs or signatures by the needed property.','Explain why a checksum needs a trusted reference.','Distinguish a real calculation from a secure deployment.'],[
 'Encryption protects the secrecy of data from people without the required key, subject to the algorithm, implementation and key handling. Hashing transforms bytes into a fixed-length digest for comparison. A hash is not encrypted data and is not normally decrypted. Encoding such as Base64 only changes representation; it is not a secrecy mechanism.',
 'SHA-256 can help detect a change when you compare a file’s digest to a trustworthy reference. The reference matters: if someone can replace both a downloaded file and the hash published next to it, a matching hash alone does not establish who supplied the file. A hash also does not tell you whether a file is safe, correct or recently created.',
 'A message authentication code, such as HMAC, combines a key with message bytes so holders of that key can check integrity and key-based authenticity. Anyone holding the shared key can produce a valid tag, so HMAC does not prove which of those holders authored a message. Do not use a published tutorial key to protect real data.',
 'A digital signature uses a private signing key and a corresponding public verification key. Verification must include trust in the public key and the intended protocol context. A certificate helps bind a key to an identity under a trust model. A valid signature proves a cryptographic relationship, not that the signed software is harmless or that a human read a contract.',
 'Encryption at rest protects selected storage threats; it does not stop a compromised running application from reading data it is authorized to decrypt. Transport protection covers a connection, not every endpoint after delivery. Backups, logs and exports can create extra copies that need their own controls. Start by locating the data, then define who and what may use it.',
 'The offline lab hashes synthetic bytes, copies a file in a newly created temporary directory and compares it after a one-byte change. It also compares HMAC tags using an explicitly public demonstration key. It never reads your files. The experiment makes integrity behavior visible; it does not generate credentials, encrypt storage or implement a production cryptographic protocol.'
 ],
 'The fictional record is “booking=17;status=confirmed”. Changing only 17 to 18 changes the SHA-256 digest. Copying the original bytes to a restored file preserves the digest. If the original and tampered files are accompanied by their own freshly computed hashes, each can pass comparison to its own hash. You still need an independent trusted reference. The HMAC demonstration rejects changed bytes under the original tag, but its published key means anyone can make a new valid tag; it is teaching data, not authentication for a real system.',
 ['Predict which comparisons should match before running the integrity command.','Run python3 labs/security-foundations/offline_lab.py integrity.','Identify identical-copy, changed-message, valid-tag and wrong-tag results.','Explain the role of the trusted baseline in a restored-file check.','Write one threat helped by storage encryption and one threat it does not solve.','Keep all examples synthetic and never substitute a real key, password or private file.'],[
 check('A file and its SHA-256 value come from the same untrusted location. Their match establishes what?', ['The file has no malware','Its bytes match that supplied digest, without independently proving publisher authenticity','The file is encrypted','The publisher’s identity is certain'],1,'A digest comparison checks bytes against a reference. The trustworthiness of that reference is a separate question.'),
 check('Which mechanism uses a shared key to authenticate message bytes?', ['Base64','A plain checksum without a key','HMAC','File compression'],2,'HMAC is keyed. Encoding, compression and unkeyed hashes do not establish the same property.'),
 check('Why can encryption at rest fail to stop theft through a compromised application?', ['Encryption never works','The running application may have legitimate decryption access','Hashing always reveals the key','A certificate automatically exports all files'],1,'Storage encryption does not remove the application’s authorized data access. Endpoint and application controls still matter.')
 ],['hash','python_hash','python_hmac'],
 ['Actual integrity command output.','Explanation of why the public demonstration key protects nothing outside the exercise.','One limitation each for hashing, storage encryption and digital signatures.'],
 'No password hashing, TLS handshake, signature verification, encryption or key-management deployment is implemented by this exercise.')

add('sec-trust-boundaries','Draw boundaries and allowed flows',
 'Use an explicit flow matrix instead of trusting a network label.',
 ['Identify a trust boundary in a simple service.','Separate network reachability from identity and application authorization.','Apply default-deny reasoning without changing a real firewall.'],[
 'Draw Cedar’s service as components: staff device, web front end, booking application, database and backup storage. Draw arrows for necessary operations, not just boxes for products. Each arrow should say who starts the communication, what it carries and why it is needed. This is a small data-flow model.',
 'A trust boundary is a place where assumptions or authority change. Moving from a staff browser to a server crosses one; moving from an application identity to a database crosses another. Input must be checked where it is used, and authority must be scoped at each boundary. A trusted internal label does not make every request legitimate.',
 'Segmentation limits allowed communication between zones or workloads. A VLAN separates Layer 2 broadcast domains; routing and enforcement determine which inter-zone flows are possible. A firewall decision may use addresses, ports, protocol or additional context. Merely placing a system in a private address range is not a complete access policy.',
 'Zero trust does not mean blocking everything or distrusting every human. It rejects automatic trust based only on location or ownership and makes access decisions around resources and context. Network controls, device state, identity checks and application permissions can complement one another. Buying a product does not by itself establish a zero-trust architecture.',
 'Choose a default-deny model for the paper exercise: a flow must match an explicit allow rule. Staff-to-web TCP 443 and application-to-database TCP 5432 may be justified; guest-to-database should not be. Port numbers are examples, not proof of protocol identity. The toy model ignores return traffic, stateful inspection, DNS, management and many operational dependencies.',
 'Test positive and negative paths. An allowed flow must support its intended user task; a denied flow must actually be denied under the specified conditions. Include failure recovery and administrative access in a real design review. Do not try the matrix against real addresses or edit your device’s network settings for this lesson.'
 ],
 'The synthetic flow matrix permits staff → web on TCP 443 and app → database on TCP 5432. It denies guest → database and staff → database because no rule justifies either. A permitted web connection still needs server identity checks and per-request authorization. If the application is compromised, its permitted database path could still be abused within its privileges. That residual risk calls for narrower database permissions, application controls and monitoring, not the claim that segmentation solved everything.',
 ['Draw the five Cedar components and label each necessary arrow.','Mark two boundaries and write the assumptions that change at them.','Predict the supplied flows.json decisions.','Run python3 labs/security-foundations/offline_lab.py flows.','Add a paper-only backup or monitoring dependency, including identity and purpose.','Explain a misuse that remains possible through an allowed flow and a separate control for it.'],[
 check('A database uses a private IP address. Which conclusion follows?', ['Every internal user is authorized','A complete security policy already exists','It is not by itself proof of access control or safe configuration','TLS is unnecessary'],2,'Address scope and authorization are different properties.'),
 check('An allowed network connection proves which result?', ['The intended application action is authorized','A network rule permits the modeled flow; other checks remain','The client is a trustworthy person','The data is backed up'],1,'Reachability is only one gate. Identity, application permissions and business correctness are separate.'),
 check('Which test is missing from a plan that checks only approved flows?', ['A check that forbidden flows are denied','A scan of unrelated public systems','A weaker password policy','A change to the real router'],0,'Negative tests show that intended boundaries are actually enforced in the modeled scope.')
 ],['zero','risk'],
 ['Labeled data-flow sketch and policy justifications.','Predicted and actual results for six synthetic flows.','One allowed-path residual risk and an appropriate separate control.'],
 'This is a pure rule comparison, not a firewall emulator, packet test, network scan or complete architecture.')

add('sec-phishing-decisions','Handle a suspicious request without escalating harm',
 'Separate message clues, business verification and safe reporting.',
 ['Recognize urgency and authority as persuasion rather than proof.','Choose a trusted verification path.','Explain why authentication signals do not guarantee a benign request.'],[
 'Social engineering persuades someone to take an action that serves the sender. Phishing can arrive by message, call, QR code or a collaboration invitation. A familiar name, a logo or correct personal details can make a request convincing without proving authority. Pressure to act quickly often tries to remove the pause in which a person would verify.',
 'Start with the requested action and its consequence. Is someone asking for a sign-in, a one-time code, an unusual payment, a new download or a change to account recovery? Compare it with the normal workflow. A real organization can send an unexpected legitimate request, so suspicious clues are reasons to verify, not proof that a particular person is guilty.',
 'Use a channel you already trust: open the known application yourself or contact the person using a previously verified directory entry. Do not use a number, reply address or login link supplied only by the suspicious request as your independent check. In this course, verification is a paper decision, not permission to contact anyone.',
 'Email protections such as SPF, DKIM and DMARC help with specific sender-domain and message-authentication checks. A message that passes them can still be malicious, for example when an attacker controls a legitimate domain or an account is compromised. A display name and the exact domain are different things. Do not teach “authentication passed” as “the business request is safe.”',
 'If a person already clicked or entered information, respond calmly and follow the organization’s approved process. Preserve useful details, report promptly, and let authorized responders decide on sessions, account recovery and device handling. Blame and embarrassment discourage early reporting. Do not ask someone to send you their password or a one-time code as evidence.',
 'Our examples are plain invented text. They contain no clickable phishing page, executable attachment or live destination. The safe skill is deciding what to verify and how to describe the uncertainty. Do not forward a suspicious message broadly, download its attachment to investigate casually, or send a payment to “test” whether it is real.'
 ],
 'A fictional message says: “I am covering finance today. We need the supplier bank details changed before 16:00. Skip the usual second approval; the manager already agreed.” The important issue is the requested financial change and bypass of an established control, not whether the grammar is good. Pause the change, verify through the known supplier-change process, and preserve the message for the approved report. You can describe the concern without accusing the named manager of misconduct.',
 ['Read the three message cards in the worksheet without opening any external destinations.','Underline the requested action, claimed authority and potential consequence.','Choose an independent verification channel for each.','Write a two-sentence internal report using observations, not accusations.','Describe what changes if the user already entered credentials, without collecting those credentials.','Explain one reason a legitimate-looking or authenticated message can still be unsafe.'],[
 check('A message requests a supplier payment change and supplies a callback number. What is the strongest independent check?', ['Call only that supplied number','Use the established supplier verification process and a previously trusted contact','Reply with account credentials','Approve because the logo looks correct'],1,'An independently established contact/process avoids using attacker-controlled evidence to verify itself.'),
 check('A message passes domain authentication. What should you conclude?', ['The business request is definitely safe','All attachments are harmless','That signal alone does not establish benign intent or authority','No further policy applies'],2,'Domain/message authentication is not a guarantee about the request’s purpose or the account holder’s intentions.'),
 check('What response best encourages useful early reporting?', ['Blame the person who clicked','Ask for their password to investigate','Tell everyone the sender is criminal','Calmly collect non-secret facts and follow the approved incident process'],3,'Prompt, nonjudgmental reporting helps responders. Secrets and unsupported allegations are unnecessary.')
 ],['phishing','identity','dmarc'],
 ['Three reasoned verification decisions.','Reports exclude credentials and unsupported accusations.','A post-click escalation path is distinguished from preventive advice.'],
 'This lesson does not send messages, investigate a real sender or provide legal conclusions about fraud.')

add('sec-vulnerability-triage','Prioritize fixes with context',
 'Move from a scanner score to a verified, owned remediation decision.',
 ['Distinguish vulnerability severity from local remediation priority.','Check inventory, exposure and evidence before choosing an action.','Verify a fix and preserve rollback.'],[
 'A vulnerability finding is a claim about a weakness, often linked to a product and version. It can be correct, incomplete, stale or a false positive. First identify the asset, owner, affected component and evidence. A software inventory helps find exposure; a component list alone does not prove whether a vulnerable feature is reachable or used.',
 'CVSS describes technical severity using defined metrics. A base score is useful context, not a complete business priority. Threat information, exploitation evidence, exposure, asset importance, existing controls and the consequences of a change all affect a local decision. Scores from different versions or metric sets should not be compared as if they were identical measurements.',
 'Ask a sequence of concrete questions. Is the affected component actually present? Is the vulnerable path exposed? Is exploitation known or observed? What would compromise cost here? Is there a tested patch or supported mitigation? Who can approve the change, and how will the result be checked? Record unknowns instead of converting them into certainty.',
 'Patch management includes finding, prioritizing, obtaining, installing and verifying updates. Plan compatibility tests, dependencies, maintenance windows and rollback. A status marked “installed” does not prove the vulnerable service restarted with the fixed component. Verification should use product-appropriate evidence and a check of the original workflow.',
 'When immediate patching is not possible, a compensating control may reduce exposure while an owner manages the remaining risk. Restricting an exposed path is not the same as removing the vulnerability. Record expiration and retest dates so a temporary exception does not silently become permanent.',
 'The synthetic table uses fictional finding IDs, not real CVEs. Its ordering rule is deliberately simple: known exploitation first, then exposure, then business impact, then severity. That is a teaching rule, not a universal organizational standard. Do not run scanners or exploit demonstrations against any real system as part of this exercise.'
 ],
 'Case A is a disconnected training VM with synthetic severity 9.8 and no essential data. Case B is an internet-facing appointment gateway with severity 8.1, known exploitation and a critical workflow. Under our stated rule B is investigated first. Case C is a critical internal database with unknown exposure, so verifying that uncertainty is a separate urgent task. The ordering is not permission to skip A indefinitely or to patch B without testing a supported change path.',
 ['Read findings.json and predict its teaching-rule order.','Run python3 labs/security-foundations/offline_lab.py triage.','Explain why the 9.8 finding is not first under the stated assumptions.','Write one verification question for every finding.','Prepare a paper-only change record with owner, test, rollback, success criteria and deadline.','Record a temporary mitigation’s residual risk and expiry.'],[
 check('Why can a lower severity finding deserve earlier attention?', ['Scores are useless','Exposure, exploitation and business impact can make the local risk higher','The oldest finding is always worst','All internal systems are safe'],1,'Severity is one input. Local context and threat evidence influence priority.'),
 check('What should happen after an update reports successful installation?', ['Declare every risk eliminated','Delete investigation records','Verify the relevant version/state and affected user workflow','Disable future monitoring'],2,'Installation is one step. Verification confirms the intended change and checks for regressions.'),
 check('A temporary access restriction reduces exposure but the vulnerable software remains. What should the record say?', ['The vulnerability is permanently gone','A time-bounded mitigation, residual risk, owner and follow-up','No further action exists','The scanner must be wrong'],1,'A compensating control and a permanent repair are different. Their status should remain explicit.')
 ],['patch','cvss'],
 ['Four known findings ordered; one unknown exposure held for verification.','A change record includes rollback and actual verification criteria.','Unknown exposure is recorded as unknown.'],
 'This exercise does not calculate official CVSS, validate a real CVE, scan assets or install patches.')

add('sec-log-evidence','Read security logs without inventing a story',
 'Build a timeline, identify gaps and distinguish an alert from a conclusion.',
 ['Separate event time from collection order.','Explain false positives, missing evidence and correlated observations.','Avoid secret or excessive personal data in logs.'],[
 'An event is an observed occurrence. An alert is a rule or system deciding that observations warrant attention. An incident is a situation handled under an organization’s response criteria. These are related but not interchangeable. A failed login is an event, not automatic proof of an attacker.',
 'Useful records say when, where, what action, which relevant identity or component and what result. Use identifiers that support correlation without collecting unnecessary private details. Passwords, session tokens and secret keys do not belong in ordinary logs. Treat log input as untrusted data, and protect log access and retention.',
 'A timeline depends on time sources. Distinguish when the source says an event occurred from when a collector received it. Normalize time zones and preserve original timestamps. Clock drift, delayed forwarding and out-of-order delivery can make a naive sort misleading. Do not infer causation merely because two lines are adjacent.',
 'A detection rule trades missed activity against distracting alerts. A threshold of three failed logins from one identity within five minutes can be useful in a toy case, but typos and a broken client may also trigger it. Distributed or slow behavior can evade it. Evaluate the rule against both expected benign and concerning examples.',
 'Correlate different evidence types. A success after several failures might reflect a real user finally remembering a password, a support reset or unauthorized access. A later export can increase concern, but you still need authority, scope and source reliability before claiming a breach. Preserve what the evidence says and mark what you do not yet know.',
 'The lab reads only a bundled synthetic JSON file, normalizes explicit time zones and counts distinct event IDs. Duplicate delivery must not inflate the count. The threshold is inclusive of a five-minute window and groups by identity, not IP. This is transparent arithmetic for learning, not a deployable detection system or an attribution tool.'
 ],
 'Cedar’s synthetic events contain three failures for dana at 09:00, 09:02 and 09:04 UTC, one duplicate copy of the 09:02 record, and a success at 09:05. Another user has two widely separated failures. The rule produces one alert for dana, based on three distinct events, not four. The success is a reason to investigate the context, not proof that dana or anyone else stole data. A 09:04 event may arrive after the 09:05 event, so preserve collection and event times separately.',
 ['Read events.json and count distinct failures by event ID.','Convert the +01:00 example to UTC by hand.','Predict which identity crosses the stated five-minute threshold.','Run python3 labs/security-foundations/offline_lab.py logs.','Write two benign explanations and one concerning explanation.','Name the next evidence needed and a fact you cannot conclude from these records.'],[
 check('A failed-login threshold fires. What does that establish?', ['The named user is guilty','The stated detection condition was met and needs context','All data was exported','The device must be wiped'],1,'An alert is a signal for triage, not a verdict or an instruction to destroy evidence.'),
 check('Why deduplicate the repeated event ID?', ['To hide inconvenient evidence','Because repeated collection is not necessarily a new authentication attempt','Because all logs are false','To make every alert disappear'],1,'The same source event can be delivered twice. Count logical events while retaining provenance.'),
 check('Which item should be excluded from an ordinary authentication log?', ['A timestamp with a time zone','A success/failure result','A session bearer token','A non-secret event identifier'],2,'A session token can grant access. Logging it creates unnecessary exposure.')
 ],['logging','incident'],
 ['Actual normalized timeline and one synthetic alert.','Duplicate event and timezone handling explained.','Observation, inference and missing evidence are separated.'],
 'No live log collection, SIEM integration, malware attribution or production detection efficacy is claimed.')

add('sec-incident-decisions','Respond while preserving choices and evidence',
 'Practice a bounded tabletop with owners, containment and recovery gates.',
 ['Distinguish preparation, detection, response and recovery.','Choose proportionate containment under authority.','Keep a decision log and communicate uncertainty.'],[
 'Incident response is coordinated work to limit harm and restore a trustworthy service. It needs authority, roles, contact paths, evidence handling and rehearsed decisions before a crisis. NIST SP 800-61 Revision 3, published in 2025, connects response to the CSF 2.0 risk-management functions. Older phase mnemonics can help organize learning, but should not be presented as the current publication’s only structure.',
 'At intake, record scope, time, symptoms, affected services and the reliability of each source. Use the organization’s severity criteria and escalation routes. A missing log may be a collection failure, a retention setting or an adversarial action. Describe it as a gap until evidence supports a stronger claim.',
 'Containment limits further harm while balancing safety, business continuity and evidence. Isolating a device, restricting a session or blocking a flow can have very different consequences. Follow an approved playbook and the responsible person’s authority. There is no universal rule to immediately shut down every machine or to always leave everything connected.',
 'Preserve originals where feasible, work from controlled copies and record collection, handling and changes. A digest can help compare copies, but a digest alone is not a chain of custody. Legal preservation requirements, specialist forensics and regulated notification decisions need qualified organizational owners. This course is a practice tabletop, not legal or forensic certification.',
 'Recovery should remove or control the cause, restore trusted components and verify the user outcome. Restoring a clean file while leaving an exposed account active can restart the incident. Decide what evidence will permit return to service, who authorizes it, what monitoring continues and when a failed validation triggers rollback or escalation.',
 'Communicate what is known, what remains uncertain, what has been done and when the next decision will occur. Keep an internal technical record separate from a customer notice or public statement. A tabletop answer is not authority to contact third parties, delete data, disable a real account or assert a confirmed breach.'
 ],
 'At 09:10 Cedar receives a synthetic alert for a departed contractor account and an unexpected export event. The facilitator states that no actual people or systems are involved. The service owner authorizes a simulated account hold; the responder records expected impact and preserves the supplied log copy. The team does not declare exfiltration from one export label. It asks whether data was actually delivered, to what destination, and whether the event record is reliable. Recovery requires removing stale access, reviewing related sessions and verifying the intended booking workflow in the tabletop.',
 ['Use the cumulative capstone’s four timed injects, one at a time.','Record observations separately from hypotheses after each inject.','Name who could authorize each proposed action and its expected side effects.','Choose a simulated containment step and evidence-preservation plan.','Write two return-to-service gates and one condition that blocks recovery.','Draft an internal status update without claiming certainty or contacting anyone.'],[
 check('An export event appears after suspicious access. What is the most defensible statement?', ['A breach of every record is proven','The export record is concerning; delivery, scope and reliability require verification','Nothing needs investigation','Every device must be erased'],1,'The evidence raises concern but does not establish all consequences or justify destructive actions.'),
 check('What is missing if a copy has a hash but no handling record?', ['A guaranteed malware cure','The history of who collected and handled the evidence','All useful integrity information','A need for any further documentation'],1,'Hashes help compare bytes. They do not replace provenance and custody records.'),
 check('Which recovery gate addresses a recurring cause?', ['A screenshot of the login page','A fast restore alone','A green progress bar','Verified removal of stale access plus successful intended workflows'],3,'Restoring service without controlling the entry condition can repeat the incident.')
 ],['incident','csf'],
 ['Decision log names authority, evidence, side effects and unresolved questions.','Two explicit recovery gates and one blocking condition.','A concise status update distinguishes known from suspected.'],
 'All response actions are simulated. This is not a forensic acquisition, breach determination or authorization to alter real systems.')

add('sec-restore-proof','Prove a restore instead of trusting a backup label',
 'Measure a synthetic recovery window and verify content separately.',
 ['Distinguish RPO, RTO and actual recovery measurements.','Explain backup independence and failure domains.','Verify a copy without claiming a complete disaster-recovery test.'],[
 'A backup is a recoverable copy made for a defined purpose. Synchronization and redundancy can replicate accidental deletion or corruption, so they do not automatically provide independent recovery points. Decide what failures must be survived: a lost disk, an account takeover, ransomware, regional loss or an accidental overwrite require different designs.',
 'Recovery point objective, or RPO, states the acceptable data-loss window measured in time. Recovery time objective, or RTO, states the target time to restore the defined service after disruption. Objectives express needs. Actual recovery time and the age of the usable restored point are measurements. Neither objective is guaranteed by a backup job’s green status.',
 'Define exactly what “recovered” means. A file can be readable while the application cannot start. A database can open while related files are from a different point in time. Include dependency order, identity access, keys, configuration and a user workflow in a real plan. Keep recovery material protected but available to the authorized recovery team.',
 'A useful restore test retrieves a selected recovery point into an isolated destination, verifies expected content and performs representative operations. Preserve the source and avoid overwriting the only remaining copy. Check whether the recovered data is trusted, not merely old. A backup that contains the same compromise may restore the problem.',
 'Cedar’s paper scenario has a disruption at 10:20 UTC, a last usable recovery point at 10:00 and validated return to service at 10:55. The measured data-loss window is 20 minutes and recovery time is 35 minutes. Against RPO 15 minutes and RTO 60 minutes, the scenario misses RPO but meets RTO. Passing one does not cancel failing the other.',
 'Our executable lab uses an isolated temporary directory and synthetic bytes for a real local copy-and-hash check. The scenario times are supplied fictional timestamps; they are not a measured disaster recovery. The temporary directory is created and cleaned by the program. It never restores over a user path and does not change backup settings.'
 ],
 'The copy experiment returns matching hashes for original and restored synthetic files, then detects a changed byte in a second copy. That is real evidence of those local file comparisons. The timing exercise separately calculates 20 minutes of potential loss and 35 minutes to service validation from invented records. An honest report says both things and identifies the missing application, dependency, key-recovery and failure-domain tests. It does not say “all backups verified” or “RPO achieved” based on one copy.',
 ['Calculate the scenario’s recovery time and data-loss window before running the tool.','Run python3 labs/security-foundations/offline_lab.py recovery.','Compare actual values with the stated RPO and RTO separately.','Run the integrity command for the actual local synthetic-copy check.','List the dependencies absent from a one-file restore.','Write an acceptance record distinguishing real local outputs from fictional timing assumptions.'],[
 check('A 20-minute loss window is compared with an RPO of 15 minutes. What is the result?', ['RPO met because the restore was fast','RPO missed by five minutes in this scenario','RTO must also fail','All data is necessarily lost'],1,'The recovery point is older than the stated acceptable loss window. Recovery speed is a different measure.'),
 check('Why is synchronization alone not sufficient evidence of a backup strategy?', ['Synchronization never transfers data','It can propagate deletion or corruption to the other copy','All replicas are offline','It always proves independence'],1,'Independent recoverable versions and failure-domain separation need deliberate design.'),
 check('A restored file’s hash matches a trusted original. What remains unproven?', ['Whether those compared bytes match','Every application dependency and end-to-end recovery workflow','The hash comparison result','The fact that the local copy exists'],1,'Byte equality is useful but narrow. It does not validate the full service and all dependencies.')
 ],['recovery','python_hash'],
 ['Correct separate RPO/RTO calculations.','Actual synthetic-copy output.','A list of untested service dependencies and failure domains.'],
 'Only the temporary file-copy check is physically executed. No real backup system, application restore, ransomware recovery or business continuity exercise is performed.')

add('sec-governance-proof','Turn controls into accountable evidence',
 'Connect policies, standards, changes and suppliers to a reviewable decision.',
 ['Distinguish a policy, standard, procedure and evidence.','Explain shared responsibility and third-party risk.','Build a small evidence packet with honest coverage limits.'],[
 'Governance makes responsibilities and decisions explicit. A policy states an organizational expectation, such as limiting sensitive-record access to approved work. A standard specifies requirements for meeting it. A procedure explains the steps. Evidence shows what happened. These documents support one another but are not interchangeable.',
 'A control owner keeps a control working; a risk owner can make the appropriate risk decision under organizational authority. An assessor checks evidence against criteria. In a small team one person may hold several roles, but conflicting duties and unchecked self-approval still need attention. Do not confuse “someone signed the form” with proof that a control operated.',
 'Changes need a purpose, scope, owner, relevant approval, testing, rollback and verification proportional to their impact. Emergency changes still need records and follow-up. Document what will stop the change, what a successful result looks like and which dependencies could be affected. A rollback should be feasible rather than a sentence copied from a template.',
 'Using a cloud or outsourced service divides responsibilities; it does not outsource all accountability. The provider may operate infrastructure while the customer still configures identities, data access, retention and use. Read the actual service model and agreement. A supplier’s certificate or questionnaire response is evidence to examine, not proof that every risk in your use case is controlled.',
 'Collect only data needed for a purpose, restrict access, retain it according to an approved schedule and dispose of it under appropriate authority. Security, privacy and legal obligations overlap but are not identical. Requirements differ by jurisdiction and data type. This lesson does not determine legal obligations or authorize sharing, deletion or a contractual commitment.',
 'Finish with an evidence packet: a scenario, an access matrix, a boundary sketch, a change plan, a log timeline, a tabletop decision record and a restore check. Label each item as observed, simulated, assumed or not tested. A course completion mark is not a certification, professional assessment or prediction of an exam score.'
 ],
 'Cedar’s policy says staff access must match current job duties. A standard sets review and leaver-handling requirements. A procedure tells an authorized operator how to compare the approved staff list with the identity inventory. Evidence includes a dated synthetic review, removed-access decisions and deny-test results. If the review missed an account, the correct record is a gap with an owner and follow-up, not a rewritten checklist pretending the review passed. A supplier-hosted booking system still requires Cedar to manage its own users and sharing choices.',
 ['Classify four worksheet statements as policy, standard, procedure or evidence.','Write a small change plan for the fictional stale-account control.','Create a two-column provider/customer responsibility list for a fictional hosted booking service.','Assemble the seven capstone artifacts and mark each evidence type.','Perform the capstone rubric review without turning points into a pass probability.','Write the next three learning gaps to compare with the issuer’s exact current exam guide.'],[
 check('Which item is evidence rather than a policy?', ['Only approved users may access bookings','All reviews must have an owner','Compare the staff list with the access list','A dated review result with recorded decisions and deny-test outputs'],3,'Evidence records actual or explicitly simulated results. A requirement or procedure is not the result.'),
 check('A provider operates the booking infrastructure. What responsibility may remain with Cedar?', ['None under any service model','Managing its users and permitted data access','Physically repairing every provider disk','Automatically accepting every new term'],1,'Responsibility depends on the service. Customer identity and data-access decisions commonly remain with the customer.'),
 check('What should a learner conclude after finishing this pack?', ['Complete Security+ readiness is proven','A 30-question result predicts an official score','A bounded foundation has been practiced; objective and practical gaps still need review','All cybersecurity work is now covered'],2,'The lessons build useful foundations without exhaustive objective coverage or independent professional assessment.')
 ],['csf','risk','patch'],
 ['Four document types correctly distinguished.','A change plan with meaningful stop/rollback criteria.','Cumulative evidence is labeled and gaps are explicit.'],
 'This is not compliance certification, legal advice, supplier due diligence or a complete Security+ course.')

